export function dispatchTopologyNavigate(target, detail) {
    if (!target)
        return;
    target.dispatchEvent(new CustomEvent("topology-navigate", {
        bubbles: true,
        detail,
    }));
}
export function resolveTopologySelectionKind(detail) {
    return detail.cause === "navigation" ? "focus" : "select";
}
export function bindTopologyNodeSelected(target, handler) {
    if (!target)
        return () => { };
    const listener = (event) => {
        const customEvent = event;
        const detail = customEvent.detail;
        if (!detail?.nodeId)
            return;
        handler(detail);
    };
    target.addEventListener("topology-node-selected", listener);
    return () => {
        target.removeEventListener("topology-node-selected", listener);
    };
}
